 "content": "from collections import deque


def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            result.append(obj)
    return result


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    # The marker color forms a corner L. Its open quadrant points to the
    # largest non-background object, which is recolored to the marker color.
    best = None
    for color in set(v for row in grid for v in row) - {bg}:
        for obj in components(grid, color):
            rs = [r for r, c in obj]
            cs = [c for r, c in obj]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            # Recognize an L with one horizontal and one vertical edge.
            top = sum((r0, c) in obj for c in range(c0, c1 + 1))
            bottom = sum((r1, c) in obj for c in range(c0, c1 + 1))
            left = sum((r, c0) in obj for r in range(r0, r1 + 1))
            right = sum((r, c1) in obj for r in range(r0, r1 + 1))
            if max(top, bottom) < 3 or max(left, right) < 3:
                continue
            # Prefer a corner L whose arms reach the grid boundary or are
            # longer than any other candidate; marker component is sparse.
            score = max(top, bottom) + max(left, right) - len(obj) * 0.01
            if best is None or score > best[0]:
                best = (score, color, obj, (r0, r1, c0, c1), top, bottom, left, right)
    if best is None:
        return out
    _, marker, guide, (r0, r1, c0, c1), top, bottom, left, right = best
    # The L's missing quadrant is the target side.
    open_up = top > bottom and left > right
    open_down = bottom > top and left > right
    open_left = (top > bottom and left < right) or (bottom > top and left < right)
    # For the common orientation (top + left arms), open quadrant is NW.
    # Determine target objects by their position relative to the guide corner.
    occupied_corner = ('top' if top >= bottom else 'bottom', 'left' if left >= right else 'right')
    if occupied_corner == ('top', 'left'):
        quadrant = lambda y, x: y < r0 and x < c0
    elif occupied_corner == ('top', 'right'):
        quadrant = lambda y, x: y < r0 and x > c1
    elif occupied_corner == ('bottom', 'left'):
        quadrant = lambda y, x: y > r1 and x < c0
    else:
        quadrant = lambda y, x: y > r1 and x > c1
    candidates = []
    for color in set(v for row in grid for v in row) - {bg, marker}:
        for obj in components(grid, color):
            if all(quadrant(y, x) for y, x in obj):
                candidates.append((len(obj), color, obj))
    if candidates:
        _, _, target = max(candidates)
        for r, c in target:
            out[r][c] = marker
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
