def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, objs = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            objs.append(obj)
    return objs


def transform(grid):
    out = [row[:] for row in grid]
    counts = {v: sum(row.count(v) for row in grid) for v in range(10)}
    bg = max(counts, key=counts.get)
    markers = []
    for color in set(v for row in grid for v in row) - {bg}:
        for obj in components(grid, color):
            rs = [r for r, c in obj]
            cs = [c for r, c in obj]
            if len(obj) < 5:
                continue
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            # Long connected Ls have one complete boundary row and column.
            for cr, cc in obj:
                for dr in (-1, 1):
                    vr = sum((cr + dr*k, cc) in obj for k in range(1, r1-r0+2))
                    for dc in (-1, 1):
                        hc = sum((cr, cc + dc*k) in obj for k in range(1, c1-c0+2))
                        if vr >= 2 and hc >= 2:
                            markers.append((len(obj), color, obj, cr, cc, dr, dc))
    if not markers:
        return out
    _, paint, marker, br, bc, dr, dc = max(markers, key=lambda x: x[0])
    # The motif to repaint is the small isolated object lying within the open
    # quadrant formed by the marker's two arms.
    candidates = []
    for color in set(v for row in grid for v in row) - {bg, paint}:
        for obj in components(grid, color):
            if obj == marker:
                continue
            inside = all((r-br)*dr < 0 and (c-bc)*dc < 0 for r, c in obj)
            if inside:
                candidates.append((len(obj), obj))
    if candidates:
        # Prefer the smallest discrete motif in the marker's open quadrant.
        target = min(candidates, key=lambda x: (x[0], -max(r for r,c in x[1])))[1]
        for r, c in target:
            out[r][c] = paint
    return out


