 "content": "from collections import Counter, deque


def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q, obj = deque([(r, c)]), set()
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            result.append(obj)
    return result


def guide_rays(obj):
    """Yield projection rays extending away from a thin L or straight bar."""
    rs = [r for r, c in obj]
    cs = [c for r, c in obj]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    # Straight vertical/horizontal bar guide.
    if len(obj) >= 4 and (c0 == c1 or r0 == r1):
        if c0 == c1:
            yield (r0, c0, -1, len(obj))
            yield (r1, c0, 1, len(obj))
        else:
            yield (r0, c0, 0, len(obj))
            yield (r0, c1, 2, len(obj))
    # Thin orthogonal L; its vertical arm supplies projection direction.
    for r in (r0, r1):
        for c in (c0, c1):
            vertical = {(y, c) for y in range(r0, r1+1)}
            horizontal = {(r, x) for x in range(c0, c1+1)}
            if vertical | horizontal == obj and (r, c) in obj and len(vertical) >= 3 and len(horizontal) >= 3:
                vdir = 1 if r == r0 else -1  # direction along vertical arm from elbow
                yield (r, c, -vdir, len(obj))


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    found = []
    for color in sorted({v for row in grid for v in row if v != bg}):
        for obj in components(grid, color):
            for r, c, direction, score in guide_rays(obj):
                if direction in (-1, 1):
                    y = r + direction
                    while 0 <= y < h and grid[y][c] == bg:
                        y += direction
                    if 0 <= y < h and grid[y][c] != color:
                        found.append((score, color, obj, (y, c)))
                else:
                    dc = -1 if direction == 0 else 1
                    x = c + dc
                    while 0 <= x < w and grid[r][x] == bg:
                        x += dc
                    if 0 <= x < w and grid[r][x] != color:
                        found.append((score, color, obj, (r, x)))
    if not found:
        return out
    # The guide is the strongest thin line/L; recolor the first object reached.
    _, marker, guide, (r, c) = max(found, key=lambda item: (item[0], len(item[2])))
    target_color = grid[r][c]
    for obj in components(grid, target_color):
        if (r, c) in obj:
            for y, x in obj:
                out[y][x] = marker
            break
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
